      "title": "Freight & Transport Services Brisbane | Road Linx Transport",
      "description": "All 14 Road Linx freight and transport services — general freight, FTL, taxi trucks, tail-lift, semi hire, hot shot, distribution and more across SE QLD.",
      "keywords": null,
      "canonical": "https://roadlinxtransport.com.au/services",
      "robots": null,
      "ogTitle": "Freight & Transport Services Brisbane | Road Linx",
      "ogDescription": "The full range of Road Linx freight and transport services across SE QLD and Northern NSW.",
      "ogUrl": "https://roadlinxtransport.com.au/services",
      "ogImage": "https://roadlinxtransport.com.au/assets/img/roadlinx-logo.png",
